import React, { useCallback, useMemo, useRef, useState } from 'react';
import './App.css';

// The preview passes useState, useEffect, useMemo, useRef, useReducer, useContext,
// createContext and useCallback in as globals; write anything else as React.x.

export type FileNode = {
  id: string;
  name: string;
  children?: FileNode[];
};

// The project tree as the API returns it: unsorted. Treat it as given.
// A node with a children array is a folder, even when the array is empty.
export const FILES: FileNode[] = [
  { id: 'readme', name: 'README.md' },
  {
    id: 'src',
    name: 'src',
    children: [
      { id: 'index-tsx', name: 'index.tsx' },
      { id: 'styles', name: 'styles', children: [] },
      { id: 'app-tsx', name: 'App.tsx' },
      {
        id: 'components',
        name: 'components',
        children: [
          { id: 'tree-tsx', name: 'Tree.tsx' },
          { id: 'button-tsx', name: 'Button.tsx' },
        ],
      },
    ],
  },
  { id: 'package-json', name: 'package.json' },
  {
    id: 'public',
    name: 'public',
    children: [
      { id: 'index-html', name: 'index.html' },
      { id: 'favicon', name: 'favicon.ico' },
    ],
  },
];

type VisibleItem = {
  node: FileNode;
  path: string;
  level: number;
  parentId: string | null;
};

const isFolder = (node: FileNode): boolean => node.children !== undefined;

function sortNodes(nodes: FileNode[]): FileNode[] {
  return [...nodes].sort((a, b) => {
    if (isFolder(a) !== isFolder(b)) return isFolder(a) ? -1 : 1;
    return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
  });
}

function buildParentMap(nodes: FileNode[], parentId: string | null, map: Map<string, string | null>) {
  for (const node of nodes) {
    map.set(node.id, parentId);
    if (node.children) buildParentMap(node.children, node.id, map);
  }
  return map;
}

const PARENT_OF = buildParentMap(FILES, null, new Map<string, string | null>());

function visibleItems(nodes: FileNode[], expanded: Set<string>, parent: VisibleItem | null): VisibleItem[] {
  return sortNodes(nodes).flatMap((node) => {
    const item: VisibleItem = {
      node,
      path: parent ? `${parent.path}/${node.name}` : node.name,
      level: parent ? parent.level + 1 : 1,
      parentId: parent ? parent.node.id : null,
    };
    const open = isFolder(node) && expanded.has(node.id);
    return open ? [item, ...visibleItems(node.children ?? [], expanded, item)] : [item];
  });
}

export default function App() {
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [activeId, setActiveId] = useState<string>(() => sortNodes(FILES)[0].id);
  const itemRefs = useRef(new Map<string, HTMLLIElement>());

  const visible = useMemo(() => visibleItems(FILES, expanded, null), [expanded]);

  // The tab stop must stay visible: if the active item sits inside a collapsed
  // folder, the nearest visible ancestor takes over.
  const tabStopId = useMemo(() => {
    const visibleIds = new Set(visible.map((item) => item.node.id));
    let id: string | null = activeId;
    while (id !== null && !visibleIds.has(id)) id = PARENT_OF.get(id) ?? null;
    return id ?? visible[0].node.id;
  }, [visible, activeId]);

  const focusItem = useCallback((id: string) => {
    setActiveId(id);
    itemRefs.current.get(id)?.focus();
  }, []);

  const toggle = useCallback((id: string) => {
    setExpanded((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const activate = (item: VisibleItem) => {
    if (isFolder(item.node)) toggle(item.node.id);
    else setSelectedPath(item.path);
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLUListElement>) => {
    const target = (event.target as HTMLElement).closest('[role="treeitem"]');
    const index = visible.findIndex((item) => item.node.id === target?.getAttribute('data-id'));
    if (index < 0) return;
    const item = visible[index];
    const open = isFolder(item.node) && expanded.has(item.node.id);
    const next = visible[index + 1];

    switch (event.key) {
      case 'ArrowDown':
        if (next) focusItem(next.node.id);
        break;
      case 'ArrowUp':
        if (index > 0) focusItem(visible[index - 1].node.id);
        break;
      case 'Home':
        focusItem(visible[0].node.id);
        break;
      case 'End':
        focusItem(visible[visible.length - 1].node.id);
        break;
      case 'ArrowRight':
        if (isFolder(item.node) && !open) toggle(item.node.id);
        else if (open && next && next.parentId === item.node.id) focusItem(next.node.id);
        break;
      case 'ArrowLeft':
        if (open) toggle(item.node.id);
        else if (item.parentId) focusItem(item.parentId);
        break;
      case 'Enter':
        activate(item);
        break;
      default:
        return;
    }
    event.preventDefault();
  };

  const renderNodes = (nodes: FileNode[], parent: VisibleItem | null): React.ReactNode =>
    sortNodes(nodes).map((node) => {
      const item: VisibleItem = {
        node,
        path: parent ? `${parent.path}/${node.name}` : node.name,
        level: parent ? parent.level + 1 : 1,
        parentId: parent ? parent.node.id : null,
      };
      const folder = isFolder(node);
      const open = folder && expanded.has(node.id);
      return (
        <li
          key={node.id}
          role="treeitem"
          data-id={node.id}
          data-path={item.path}
          aria-level={item.level}
          aria-expanded={folder ? open : undefined}
          aria-selected={folder ? undefined : selectedPath === item.path}
          tabIndex={tabStopId === node.id ? 0 : -1}
          className={folder ? 'item item--folder' : 'item item--file'}
          ref={(element) => {
            if (element) itemRefs.current.set(node.id, element);
            else itemRefs.current.delete(node.id);
          }}
          onFocus={(event) => {
            if (event.target === event.currentTarget) setActiveId(node.id);
          }}
        >
          <span
            className="row"
            style={{ paddingLeft: `${(item.level - 1) * 18 + 10}px` }}
            onClick={() => {
              focusItem(node.id);
              activate(item);
            }}
          >
            <span className="icon" aria-hidden="true">{folder ? (open ? '▾' : '▸') : '•'}</span>
            <span className="name">{node.name}</span>
          </span>
          {open && (
            <ul role="group">
              {node.children && node.children.length > 0 ? (
                renderNodes(node.children, item)
              ) : (
                <li role="none" className="empty" style={{ paddingLeft: `${item.level * 18 + 10}px` }}>
                  Empty folder
                </li>
              )}
            </ul>
          )}
        </li>
      );
    });

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Project files</h1>
          <p className="subtitle">Arrow keys move, Right opens, Left closes, Enter selects.</p>
        </header>
        <div className="toolbar">
          <button type="button" className="collapse-all" onClick={() => setExpanded(new Set())}>
            Collapse all
          </button>
          <p className="selection" aria-live="polite">
            {selectedPath ? `Selected: ${selectedPath}` : 'Nothing selected'}
          </p>
        </div>
        <ul role="tree" aria-label="Project files" className="tree" onKeyDown={onKeyDown}>
          {renderNodes(FILES, null)}
        </ul>
      </section>
    </main>
  );
}
